import sys
from collections import deque

sys.setrecursionlimit(1 << 22)


def main():
    n = 7
    edges = [(1, 2), (1, 3), (2, 4), (2, 5), (3, 6), (3, 7)]
    K = 2
    G = [[] for _ in range(n + 1)]
    for a, b in edges:
        G[a].append(b)
        G[b].append(a)

    removed = [False] * (n + 1)
    siz = [0] * (n + 1)
    tf = {0: 1}
    touched = [0]
    ans = 0

    def get_size(u, f):
        siz[u] = 1
        for v in G[u]:
            if v != f and not removed[v]:
                siz[u] += get_size(v, u)
        return siz[u]

    def get_centroid(u, tot, f):
        for v in G[u]:
            if v != f and not removed[v] and siz[v] * 2 > tot:
                return get_centroid(v, tot, u)
        return u

    def collect(u, f, d, out):
        if d > K:
            return
        out.append(d)
        for v in G[u]:
            if v != f and not removed[v]:
                collect(v, u, d + 1, out)

    def decompose(u):
        nonlocal ans
        tot = get_size(u, 0)
        rt = get_centroid(u, tot, 0)
        # 统计经过 rt 且距离恰为 K 的点对
        for ch in G[rt]:
            if removed[ch]:
                continue
            dists = []
            collect(ch, rt, 1, dists)
            for d in dists:
                ans += tf.get(K - d, 0)
            for d in dists:
                tf[d] = tf.get(d, 0) + 1
                touched.append(d)
        # 回滚本层 tf（只清改动过的下标，避免 O(n^2)）
        for d in touched:
            tf[d] = 0
        touched.clear()
        tf[0] = 1
        touched.append(0)
        removed[rt] = True
        for v in G[rt]:
            if not removed[v]:
                decompose(v)

    decompose(1)
    print("pairs with distance =", K, ":", ans)
    # 手算：距离2的点对 (1,4),(1,5),(1,6),(1,7),(2,3),(4,5),(6,7) 共 7 对
    assert ans == 7, ans
    print("OK")


if __name__ == "__main__":
    main()
